import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useSite } from '../context/SiteContext';
import { Menu, X, ArrowRight, ShieldCheck } from 'lucide-react';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const { content, isLoggedIn, logout } = useSite();
  const location = useLocation();
  const isAdmin = location.pathname.startsWith('/admin');

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  if (isAdmin) {
    return <div className="min-h-screen bg-slate-900 text-white">{children}</div>;
  }

  return (
    <div className="min-h-screen flex flex-col bg-[#0B1120] text-slate-100 font-light overflow-x-hidden selection:bg-blue-500 selection:text-white">
      {/* Navigation */}
      <nav
        className={`fixed w-full z-50 transition-all duration-300 border-b border-transparent ${
          isScrolled ? 'bg-[#0B1120]/90 backdrop-blur-md border-white/10 py-4 shadow-xl' : 'bg-transparent py-6'
        }`}
      >
        <div className="container mx-auto px-6 flex justify-between items-center">
          <Link to="/" className="text-2xl font-bold tracking-tighter text-white flex items-center gap-2">
            <span className="bg-blue-600 w-8 h-8 flex items-center justify-center rounded-lg text-lg">A</span>
            APICK
          </Link>

          <div className="hidden md:flex items-center space-x-8 text-sm font-medium text-slate-300">
            <Link to="/" className="hover:text-white transition-colors">홈</Link>
            <Link to="/services" className="hover:text-white transition-colors">서비스</Link>
            <Link to="/portfolio" className="hover:text-white transition-colors">포트폴리오</Link>
            <Link to="/blog" className="hover:text-white transition-colors">인사이트</Link>
            {isLoggedIn ? (
              <div className="flex items-center gap-4 ml-4 pl-4 border-l border-white/10">
                <Link to="/admin" className="text-blue-400 hover:text-blue-300">관리자</Link>
                <button onClick={logout} className="text-slate-400 hover:text-white">로그아웃</button>
              </div>
            ) : (
               <Link to="/admin" className="flex items-center gap-1 text-slate-500 hover:text-slate-300 text-xs">
                <ShieldCheck size={14} /> 관리자
               </Link>
            )}
            <Link
              to="/contact"
              className="bg-white text-slate-900 px-5 py-2.5 rounded-full font-bold hover:bg-blue-50 transition-all transform hover:scale-105 flex items-center gap-2"
            >
              문의하기 <ArrowRight size={16} />
            </Link>
          </div>

          <button
            className="md:hidden text-white"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          >
            {isMobileMenuOpen ? <X /> : <Menu />}
          </button>
        </div>

